import sys


def main():
    group_of = {}
    groups = []

    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        names = line.split()

        if len(names) == 1:
            name = names[0]
            if name not in group_of:
                group_index = len(groups)
                groups.append(set())
                group_of[name] = group_index
        else:
            first_name = names[0]
            second_name = names[1]
            if first_name == second_name:
                name = first_name
                if name not in group_of:
                    group_index = len(groups)
                    groups.append(set())
                    group_of[name] = group_index
            else:
                if first_name not in group_of:
                    group_index_a = len(groups)
                    groups.append(set())
                    group_of[first_name] = group_index_a
                if second_name not in group_of:
                    group_index_b = len(groups)
                    groups.append(set())
                    group_of[second_name] = group_index_b

                if group_of[first_name] != group_of[second_name]:
                    group_a = groups[group_of[first_name]]
                    group_b = groups[group_of[second_name]]

                    if len(group_a) > len(group_b):
                        group_a.update(group_b)
                        for name in group_b:
                            group_of[name] = group_of[first_name]
                    else:
                        group_b.update(group_a)
                        for name in group_a:
                            group_of[name] = group_of[second_name]

    groups.sort(key=lambda s: (-len(s), min(s)))
    for group in groups:
        print(" ".join(sorted(group)))
    return


if __name__ == "__main__":
    main()
